UPDATE tools SET faq = $x$[{"q": "Was ist Krea AI?", "a": "Krea AI ist eine KI-Kreativplattform mit Echtzeit-Bildgenerierung (das Bild aktualisiert sich während der Eingabe), einer KI-Leinwand zum Bearbeiten und Verbessern von Bildern, Videogenerierung und KI-Training auf Basis eigener Bilder."}, {"q": "Ist Krea AI kostenlos?", "a": "Krea AI bietet einen kostenlosen Plan mit 100 Compute-Einheiten pro Tag und ohne erforderliche Kreditkarte, wobei der Videozugriff eingeschränkt und das Upscaling auf 2K begrenzt ist. Kostenpflichtige Pläne beginnen mit Basic für 9 $/Monat (5 $/Monat bei jährlicher Abrechnung), gefolgt von Pro für 35 $/Monat (21 $/Monat bei jährlicher Abrechnung) und Max für 105 $/Monat (63 $/Monat bei jährlicher Abrechnung) für mehr Einheiten, schnellere Verarbeitung und höhere Parallelität."}, {"q": "Kann Krea AI Videos generieren?", "a": "Ja. Krea AI verfügt über Videogenerierungsfunktionen — Text-zu-Video und Bild-zu-Video. Die Qualität ist mit anderen Tools im mittleren Segment konkurrenzfähig, liegt aber im Allgemeinen unter der von Runway oder Kling für professionelle Videoproduktion."}]$x$::jsonb
