UPDATE tools SET faq = $x$[{"q": "O que é o Krea AI?", "a": "Krea AI é uma plataforma criativa de IA com geração de imagens em tempo real (a imagem é atualizada conforme você digita), um canvas de IA para editar e aprimorar imagens, geração de vídeo e treinamento de IA com suas próprias imagens."}, {"q": "O Krea AI é gratuito?", "a": "O Krea AI tem um plano gratuito com 100 unidades de computação por dia e sem necessidade de cartão de crédito, embora seu acesso a vídeo seja limitado e o upscaling seja limitado a 2K. Os planos pagos começam com o Basic por US$ 9/mês (US$ 5/mês na cobrança anual), com o Pro a US$ 35/mês (US$ 21/mês na cobrança anual) e o Max a US$ 105/mês (US$ 63/mês na cobrança anual) para mais unidades, processamento mais rápido e maior concorrência."}, {"q": "O Krea AI pode gerar vídeo?", "a": "Sim. O Krea AI tem recursos de geração de vídeo — texto para vídeo e imagem para vídeo. A qualidade é competitiva com outras ferramentas de nível intermediário, mas geralmente inferior ao Runway ou ao Kling para produção de vídeo profissional."}]$x$::jsonb
