UPDATE tools SET faq = $x$[{"q": "Is FLUX better than Stable Diffusion?", "a": "Black Forest Labs' Flux models, now including FLUX 3, are generally regarded as producing sharper, more photorealistic results with better text and hand rendering than SDXL. Stable Diffusion still has a larger community ecosystem of fine-tuned models, LoRAs, and tools built around it."}, {"q": "Can I run FLUX locally?", "a": "Yes. Open-weight variants such as FLUX.1 [schnell], FLUX.2 [dev], FLUX.2 [klein], and FLUX 3 Image Klein (available on Hugging Face as black-forest-labs/flux-3-image-klein and -klein-base) can be run locally via ComfyUI or Diffusers, including on consumer GeForce RTX GPUs with as little as 8GB VRAM; other VRAM requirements vary by model size and quantization."}, {"q": "What is FLUX.1?", "a": "FLUX.1 was Black Forest Labs' original model generation, released in August 2024, offered in Schnell (fast, open weights), Dev (open weights, non-commercial), and Pro (API only) tiers. It has since been superseded by FLUX.2 and FLUX 3, though FLUX.1 tiers such as Kontext and Pro Ultra remain listed and available."}]$x$::jsonb
