 WHERE slug = 'flux' AND lang = 'es';

UPDATE tools SET cons = ARRAY[$x$Los modelos de primer nivel FLUX 3 Image/Video y FLUX.2 [pro]/[max] solo están disponibles por API y de pago; no hay un nivel alojado gratuito$x$, $x$La facturación por imagen y por segundo escala con la resolución y la duración, llegando a más de $0,60/imagen a 4k y hasta $0,80/segundo para FLUX 3 Video$x$, $x$La calculadora de precios del proveedor ha mostrado cifras predeterminadas distintas de sus precios publicados 'desde' para algunos niveles de FLUX.2$x$, $x$Los pesos abiertos conllevan restricciones de licencia: el uso comercial gratuito de FLUX 3 Image Klein solo aplica a empresas con ingresos anuales inferiores a $5M, FLUX.1 [dev] sigue siendo de uso no comercial, y el autoalojamiento a mayor escala necesita una licencia de pago independiente$x$, $x$Una línea creciente entre FLUX 3, FLUX.2 y los niveles heredados de FLUX.1 puede resultar confusa a la hora de elegir un modelo$x$]::text[]
