UPDATE tools SET faq = $x$[{"q": "¿Es FLUX mejor que Stable Diffusion?", "a": "Los modelos Flux de Black Forest Labs, ahora incluyendo FLUX 3, generalmente se consideran capaces de producir resultados más nítidos y fotorrealistas, con mejor renderizado de texto y manos que SDXL. Stable Diffusion aún cuenta con un ecosistema comunitario más grande de modelos ajustados, LoRAs y herramientas construidas a su alrededor."}, {"q": "¿Puedo ejecutar FLUX localmente?", "a": "Sí. Las variantes de peso abierto como FLUX.1 [schnell], FLUX.2 [dev], FLUX.2 [klein] y FLUX 3 Image Klein (disponible en Hugging Face como black-forest-labs/flux-3-image-klein y -klein-base) se pueden ejecutar localmente mediante ComfyUI o Diffusers, incluso en GPUs GeForce RTX de consumo con tan solo 8 GB de VRAM; otros requisitos de VRAM varían según el tamaño del modelo y la cuantización."}, {"q": "¿Qué es FLUX.1?", "a": "FLUX.1 fue la generación original de modelos de Black Forest Labs, lanzada en agosto de 2024, ofrecida en los niveles Schnell (rápido, peso abierto), Dev (peso abierto, no comercial) y Pro (solo API). Desde entonces ha sido sustituida por FLUX.2 y FLUX 3, aunque los niveles de FLUX.1 como Kontext y Pro Ultra siguen listados y disponibles."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'es';

