UPDATE tools SET faq = $x$[{"q": "Ist FLUX besser als Stable Diffusion?", "a": "Die Flux-Modelle von Black Forest Labs, inzwischen einschließlich FLUX 3, gelten allgemein als schärfer und fotorealistischer mit besserer Text- und Handdarstellung als SDXL. Stable Diffusion verfügt jedoch weiterhin über ein größeres Community-Ökosystem an feinabgestimmten Modellen, LoRAs und darauf aufbauenden Tools."}, {"q": "Kann ich FLUX lokal ausführen?", "a": "Ja. Open-Weight-Varianten wie FLUX.1 [schnell], FLUX.2 [dev], FLUX.2 [klein] und FLUX 3 Image Klein (auf Hugging Face verfügbar als black-forest-labs/flux-3-image-klein und -klein-base) lassen sich lokal über ComfyUI oder Diffusers ausführen, auch auf handelsüblichen GeForce-RTX-GPUs mit nur 8 GB VRAM; weitere VRAM-Anforderungen hängen von Modellgröße und Quantisierung ab."}, {"q": "Was ist FLUX.1?", "a": "FLUX.1 war die ursprüngliche Modellgeneration von Black Forest Labs, veröffentlicht im August 2024, angeboten in den Stufen Schnell (schnell, offene Gewichte), Dev (offene Gewichte, nicht-kommerziell) und Pro (nur API). Sie wurde inzwischen von FLUX.2 und FLUX 3 abgelöst, obwohl FLUX.1-Stufen wie Kontext und Pro Ultra weiterhin gelistet und verfügbar sind."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'de';

