UPDATE tools SET cons = ARRAY[$x$Топовые модели FLUX 3 Image/Video и FLUX.2 [pro]/[max] доступны только через платный API; бесплатного хостингового уровня нет$x$, $x$Оплата за изображение и за секунду масштабируется в зависимости от разрешения и длительности, достигая более $0,60 за изображение при 4k и до $0,80 за секунду для FLUX 3 Video$x$, $x$Калькулятор цен поставщика показывал иные значения по умолчанию, чем опубликованные цены «от», для некоторых уровней FLUX.2$x$, $x$Открытые веса сопровождаются лицензионными ограничениями: бесплатное коммерческое использование FLUX 3 Image Klein распространяется только на компании с годовым доходом менее $5 млн, FLUX.1 [dev] остаётся некоммерческой, а для крупномасштабного самостоятельного хостинга требуется отдельная платная лицензия$x$, $x$Растущая линейка из уровней FLUX 3, FLUX.2 и устаревших FLUX.1 может сбивать с толку при выборе модели$x$]::text[]
