UPDATE tools SET faq = $x$[{"q": "האם FLUX טוב יותר מ-Stable Diffusion?", "a": "מודלי Flux של Black Forest Labs, הכוללים כעת גם את FLUX 3, נחשבים בדרך כלל כמייצרים תוצאות חדות ופוטו-ריאליסטיות יותר עם רינדור טקסט וידיים טובים יותר בהשוואה ל-SDXL. ל-Stable Diffusion עדיין יש מערכת אקולוגית קהילתית גדולה יותר של מודלים מכוונים, LoRAs וכלים הבנויים סביבו."}, {"q": "האם ניתן להריץ את FLUX באופן מקומי?", "a": "כן. וריאנטים בעלי משקולות פתוחות כגון FLUX.1 [schnell], FLUX.2 [dev], FLUX.2 [klein], ו-FLUX 3 Image Klein (זמין ב-Hugging Face בשם black-forest-labs/flux-3-image-klein ו--klein-base) ניתנים להרצה מקומית דרך ComfyUI או Diffusers, כולל על כרטיסי GeForce RTX צרכניים עם VRAM של 8GB בלבד; דרישות VRAM אחרות משתנות בהתאם לגודל המודל ולכימות."}, {"q": "מהו FLUX.1?", "a": "FLUX.1 היה דור המודלים המקורי של Black Forest Labs, שיצא באוגוסט 2024, והוצע בדרגות Schnell (מהיר, משקולות פתוחות), Dev (משקולות פתוחות, לא-מסחרי), ו-Pro (API בלבד). מאז הוחלף על ידי FLUX.2 ו-FLUX 3, אם כי דרגות FLUX.1 כגון Kontext ו-Pro Ultra עדיין מופיעות וזמינות."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'he';

UPDATE tools SET best_for = $x$Génération d'images et vidéos par IA, audio natif, rendu de texte, édition multi-référence, modèles à poids ouverts auto-hébergeables$x$
