 WHERE slug = 'flux' AND lang = 'fr';

UPDATE tools SET cons = ARRAY[$x$Les modèles haut de gamme FLUX 3 Image/Video et FLUX.2 [pro]/[max] sont uniquement accessibles par API et payants ; il n'existe pas de niveau hébergé gratuit$x$, $x$La facturation par image et par seconde évolue avec la résolution et la durée, atteignant plus de 0,60 $/image en 4k et jusqu'à 0,80 $/seconde pour FLUX 3 Video$x$, $x$Le calculateur de tarification du fournisseur a affiché des chiffres par défaut différents de ses prix « à partir de » publiés pour certains niveaux FLUX.2$x$, $x$Les poids ouverts comportent des restrictions de licence : l'usage commercial gratuit de FLUX 3 Image Klein ne s'applique qu'aux entreprises dont le chiffre d'affaires annuel est inférieur à 5 M$, FLUX.1 [dev] reste non commercial, et l'auto-hébergement à plus grande échelle nécessite une licence payante distincte$x$, $x$Une gamme croissante entre FLUX 3, FLUX.2 et les niveaux FLUX.1 historiques peut prêter à confusion au moment de choisir un modèle$x$]::text[]
 WHERE slug = 'flux' AND lang = 'fr';

