UPDATE tools SET faq = $x$[{"q": "FLUX est-il meilleur que Stable Diffusion ?", "a": "Les modèles Flux de Black Forest Labs, incluant désormais FLUX 3, sont généralement considérés comme produisant des résultats plus nets et plus photoréalistes, avec un meilleur rendu du texte et des mains que SDXL. Stable Diffusion conserve un écosystème communautaire plus large de modèles affinés, de LoRAs et d'outils construits autour de lui."}, {"q": "Puis-je exécuter FLUX localement ?", "a": "Oui. Les variantes à poids ouverts telles que FLUX.1 [schnell], FLUX.2 [dev], FLUX.2 [klein], et FLUX 3 Image Klein (disponible sur Hugging Face sous black-forest-labs/flux-3-image-klein et -klein-base) peuvent être exécutées localement via ComfyUI ou Diffusers, y compris sur des GPU GeForce RTX grand public avec aussi peu que 8 Go de VRAM ; les autres besoins en VRAM varient selon la taille du modèle et la quantification."}, {"q": "Qu'est-ce que FLUX.1 ?", "a": "FLUX.1 était la génération de modèles originale de Black Forest Labs, publiée en août 2024, proposée en niveaux Schnell (rapide, poids ouverts), Dev (poids ouverts, non commercial), et Pro (API uniquement). Elle a depuis été remplacée par FLUX.2 et FLUX 3, bien que des niveaux FLUX.1 tels que Kontext et Pro Ultra restent listés et disponibles."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'fr';

