 WHERE slug = 'flux' AND lang = 'pt';

UPDATE tools SET cons = ARRAY[$x$Os modelos de ponta FLUX 3 Image/Video e FLUX.2 [pro]/[max] são apenas via API e pagos; não há nível hospedado gratuito$x$, $x$A cobrança por imagem e por segundo escala com resolução e duração, chegando a mais de $0,60/imagem em 4k e até $0,80/segundo para o FLUX 3 Video$x$, $x$A calculadora de preços do fornecedor mostrou valores padrão diferentes dos preços 'a partir de' publicados para alguns níveis do FLUX.2$x$, $x$Os pesos abertos têm restrições de licença: o uso comercial gratuito do FLUX 3 Image Klein aplica-se apenas a empresas com receita anual abaixo de $5 milhões, o FLUX.1 [dev] permanece não comercial, e a auto-hospedagem em maior escala exige uma licença paga separada$x$, $x$Uma linha crescente entre FLUX 3, FLUX.2 e níveis legados do FLUX.1 pode gerar confusão na escolha de um modelo$x$]::text[]
