UPDATE tools SET faq = $x$[{"q": "O FLUX é melhor que o Stable Diffusion?", "a": "Os modelos Flux da Black Forest Labs, agora incluindo o FLUX 3, são geralmente considerados como produzindo resultados mais nítidos e fotorrealistas, com melhor renderização de texto e mãos do que o SDXL. O Stable Diffusion ainda tem um ecossistema de comunidade maior, com modelos ajustados, LoRAs e ferramentas construídas em torno dele."}, {"q": "Posso rodar o FLUX localmente?", "a": "Sim. Variantes de pesos abertos como o FLUX.1 [schnell], FLUX.2 [dev], FLUX.2 [klein] e o FLUX 3 Image Klein (disponível no Hugging Face como black-forest-labs/flux-3-image-klein e -klein-base) podem ser executadas localmente via ComfyUI ou Diffusers, inclusive em GPUs GeForce RTX de consumo com apenas 8GB de VRAM; outros requisitos de VRAM variam conforme o tamanho do modelo e a quantização."}, {"q": "O que é o FLUX.1?", "a": "O FLUX.1 foi a geração original de modelos da Black Forest Labs, lançada em agosto de 2024, oferecida nos níveis Schnell (rápido, pesos abertos), Dev (pesos abertos, não comercial) e Pro (apenas via API). Desde então foi sucedido pelo FLUX.2 e pelo FLUX 3, embora níveis do FLUX.1 como Kontext e Pro Ultra permaneçam listados e disponíveis."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'pt';

