UPDATE tools SET faq = $x$[{"q": "¿Qué es Recraft AI?", "a": "Recraft AI es un generador de imágenes con IA especializado en gráficos vectoriales y diseño coherente con la marca. A diferencia de la mayoría de herramientas de IA que producen imágenes rasterizadas, Recraft puede generar archivos vectoriales SVG reales, conjuntos de iconos y activos de marca escalables. Es popular entre diseñadores que necesitan archivos de diseño listos para producción."}, {"q": "¿Puede Recraft AI generar archivos SVG?", "a": "Sí. Este es el principal diferenciador de Recraft: genera archivos SVG (gráficos vectoriales escalables) reales que pueden escalarse a cualquier tamaño sin pérdida de calidad. Esto lo hace esencial para el diseño de logotipos, la creación de iconos y cualquier trabajo de diseño para impresión o gran formato."}, {"q": "¿Es gratis Recraft AI?", "a": "El plan gratuito de Recraft ofrece créditos gratuitos limitados: tres generaciones por estilo al día, tres subidas al día, hasta dos imágenes por generación, y solo los modelos propios de Recraft. Las imágenes del plan gratuito son públicas, propiedad de Recraft, y no están licenciadas para uso comercial. Los planes de pago empiezan en 10 $/mes facturado anualmente para Basic (1.000 créditos/mes con derechos comerciales), con Pro desde 16 $/mes facturado anualmente por 2.000 créditos, además de opciones Teams y Enterprise personalizadas."}, {"q": "¿Cuál es la diferencia entre Recraft y Midjourney para trabajos de diseño?", "a": "Recraft está optimizado para activos de diseño: vectores, iconos, visuales de marca coherentes. Midjourney está optimizado para la calidad artística de la imagen. Los diseñadores que necesitan archivos de producción usan Recraft; los artistas y profesionales creativos usan Midjourney. Muchos diseñadores usan ambos para fines diferentes."}]$x$::jsonb
 WHERE slug = 'recraft-ai' AND lang = 'es';

