UPDATE tools SET faq = $x$[{"q": "Was ist Recraft AI?", "a": "Recraft AI ist ein KI-Bildgenerator, der auf Vektorgrafiken und markenkonsistentes Design spezialisiert ist. Im Gegensatz zu den meisten KI-Tools, die Rasterbilder erzeugen, kann Recraft echte SVG-Vektordateien, Icon-Sets und skalierbare Markenassets generieren. Es ist bei Designern beliebt, die produktionsreife Designdateien benötigen."}, {"q": "Kann Recraft AI SVG-Dateien generieren?", "a": "Ja. Dies ist das wichtigste Unterscheidungsmerkmal von Recraft - es erzeugt echte SVG-Dateien (skalierbare Vektorgrafiken), die ohne Qualitätsverlust auf jede Größe skaliert werden können. Das macht das Tool unverzichtbar für Logodesign, Icon-Erstellung und jede Druck- oder Großformat-Designarbeit."}, {"q": "Ist Recraft AI kostenlos?", "a": "Recrafts kostenloser Plan bietet begrenzte kostenlose Credits: drei Generierungen pro Stil und Tag, drei Uploads pro Tag, bis zu zwei Bilder pro Generierung und nur Recrafts eigene Modelle. Bilder aus dem kostenlosen Plan sind öffentlich, gehören Recraft und sind nicht für die kommerzielle Nutzung lizenziert. Kostenpflichtige Pläne beginnen bei 10 $/Monat bei jährlicher Abrechnung für Basic (1.000 Credits/Monat mit kommerziellen Rechten), Pro startet bei 16 $/Monat bei jährlicher Abrechnung für 2.000 Credits, dazu kommen Teams- und individuelle Enterprise-Optionen."}, {"q": "Was ist der Unterschied zwischen Recraft und Midjourney für Designarbeit?", "a": "Recraft ist auf Design-Assets optimiert - Vektoren, Icons, konsistente Markenvisuals. Midjourney ist auf künstlerische Bildqualität optimiert. Designer, die produktionsreife Dateien benötigen, nutzen Recraft; Künstler und Kreativschaffende nutzen Midjourney. Viele Designer verwenden beide für unterschiedliche Zwecke."}]$x$::jsonb
 WHERE slug = 'recraft-ai' AND lang = 'de';

