UPDATE tools SET faq = $x$[{"q": "Что такое Recraft AI?", "a": "Recraft AI — это AI-генератор изображений, специализирующийся на векторной графике и дизайне с единым фирменным стилем. В отличие от большинства AI-инструментов, создающих растровые изображения, Recraft может генерировать настоящие SVG-векторные файлы, наборы иконок и масштабируемые фирменные ассеты. Он популярен среди дизайнеров, которым нужны готовые к производству дизайн-файлы."}, {"q": "Может ли Recraft AI генерировать SVG-файлы?", "a": "Да. Это главная отличительная особенность Recraft — он генерирует настоящие SVG-файлы (масштабируемая векторная графика), которые можно увеличивать до любого размера без потери качества. Это делает его незаменимым для создания логотипов, иконок и любых работ в печати или крупноформатном дизайне."}, {"q": "Бесплатен ли Recraft AI?", "a": "Бесплатный план Recraft предлагает ограниченное количество бесплатных кредитов: три генерации на стиль в день, три загрузки в день, до двух изображений за одну генерацию и только собственные модели Recraft. Изображения на бесплатном плане публичны, принадлежат Recraft и не лицензированы для коммерческого использования. Платные планы начинаются от $10/месяц при годовой оплате для Basic (1000 кредитов/месяц с коммерческими правами), план Pro начинается от $16/месяц при годовой оплате за 2000 кредитов, а также доступны план Teams и индивидуальный план Enterprise."}, {"q": "В чем разница между Recraft и Midjourney для дизайн-работы?", "a": "Recraft оптимизирован для создания дизайн-ассетов — векторов, иконок, визуалов с единым фирменным стилем. Midjourney оптимизирован для художественного качества изображений. Дизайнеры, которым нужны готовые к производству файлы, используют Recraft; художники и творческие профессионалы используют Midjourney. Многие дизайнеры используют оба инструмента для разных задач."}]$x$::jsonb
 WHERE slug = 'recraft-ai' AND lang = 'ru';

