UPDATE tools SET faq = $x$[{"q": "Що таке Recraft AI?", "a": "Recraft AI — це генератор AI-зображень, спеціалізований на векторній графіці та дизайні, узгодженому з брендом. На відміну від більшості AI-інструментів, що створюють растрові зображення, Recraft може генерувати справжні SVG-файли, набори іконок та масштабовані брендові активи. Він популярний серед дизайнерів, яким потрібні готові до виробництва файли дизайну."}, {"q": "Чи може Recraft AI генерувати SVG-файли?", "a": "Так. Це головна відмінність Recraft — він генерує справжні SVG (масштабовані векторні графіки) файли, які можна масштабувати до будь-якого розміру без втрати якості. Це робить його незамінним для дизайну логотипів, створення іконок та будь-якої друкованої або великоформатної дизайнерської роботи."}, {"q": "Чи безкоштовний Recraft AI?", "a": "Безкоштовний план Recraft пропонує обмежену кількість безкоштовних кредитів: три генерації на стиль на день, три завантаження на день, до двох зображень за одну генерацію, і лише власні моделі Recraft. Зображення безкоштовного плану публічні, належать Recraft і не ліцензовані для комерційного використання. Платні плани починаються від $10/місяць за річної оплати для Basic (1000 кредитів/місяць з комерційними правами), Pro — від $16/місяць за річної оплати за 2000 кредитів, а також доступні плани Teams та індивідуальні плани Enterprise."}, {"q": "У чому різниця між Recraft та Midjourney для дизайнерської роботи?", "a": "Recraft оптимізований для дизайнерських активів — векторів, іконок, узгоджених брендових візуалів. Midjourney оптимізований для художньої якості зображень. Дизайнери, яким потрібні готові до виробництва файли, використовують Recraft; художники та творчі професіонали використовують Midjourney. Багато дизайнерів використовують обидва для різних цілей."}]$x$::jsonb
