UPDATE tools SET faq = $x$[{"q": "מהו Recraft AI?", "a": "Recraft AI הוא מחולל תמונות AI המתמחה בגרפיקה וקטורית ובעיצוב עקבי למותג. בניגוד לרוב כלי ה-AI המפיקים תמונות רסטר, Recraft יכול לייצר קובצי SVG וקטוריים אמיתיים, ערכות אייקונים ונכסי מותג הניתנים לשינוי גודל. הוא פופולרי בקרב מעצבים הזקוקים לקבצי עיצוב מוכנים לייצור."}, {"q": "האם Recraft AI יכול לייצר קובצי SVG?", "a": "כן. זהו הייחוד המרכזי של Recraft - הוא מייצר קובצי SVG (גרפיקה וקטורית הניתנת להתאמה בקנה מידה) אמיתיים שניתן להגדיל לכל גודל ללא אובדן איכות. זה הופך אותו לחיוני לעיצוב לוגואים, יצירת אייקונים וכל עבודת עיצוב להדפסה או לפורמט גדול."}, {"q": "האם Recraft AI חינמי?", "a": "התוכנית החינמית של Recraft מציעה קרדיטים חינמיים מוגבלים: שלוש יצירות לכל סגנון ביום, שלוש העלאות ביום, עד שתי תמונות ליצירה, ואך ורק מודלים של Recraft עצמה. תמונות בתוכנית החינמית ציבוריות, בבעלות Recraft, וללא רישיון לשימוש מסחרי. תוכניות בתשלום מתחילות ב-10$/חודש בחיוב שנתי לתוכנית Basic (1,000 קרדיטים/חודש עם זכויות מסחריות), כאשר Pro מתחילה ב-16$/חודש בחיוב שנתי עבור 2,000 קרדיטים, בנוסף לאפשרויות Teams ו-Enterprise מותאמות אישית."}, {"q": "מה ההבדל בין Recraft ל-Midjourney בעבודת עיצוב?", "a": "Recraft מותאם לנכסי עיצוב - וקטורים, אייקונים, ויזואליה עקבית למותג. Midjourney מותאם לאיכות אמנותית של תמונות. מעצבים הזקוקים לקבצי ייצור משתמשים ב-Recraft; אמנים ואנשי מקצוע יצירתיים משתמשים ב-Midjourney. מעצבים רבים משתמשים בשניהם למטרות שונות."}]$x$::jsonb
 WHERE slug = 'recraft-ai' AND lang = 'he';

