UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Recraft AI ?", "a": "Recraft AI est un générateur d'images par IA spécialisé dans les graphiques vectoriels et le design cohérent avec la marque. Contrairement à la plupart des outils d'IA qui produisent des images raster, Recraft peut générer de véritables fichiers vectoriels SVG, des jeux d'icônes et des assets de marque adaptables à toute échelle. Il est populaire auprès des designers qui ont besoin de fichiers de design prêts pour la production."}, {"q": "Recraft AI peut-il générer des fichiers SVG ?", "a": "Oui. C'est le principal élément différenciateur de Recraft - il génère de véritables fichiers SVG (graphiques vectoriels adaptables) pouvant être redimensionnés à n'importe quelle taille sans perte de qualité. Cela en fait un outil essentiel pour la création de logos, d'icônes et tout travail de design pour l'impression ou le grand format."}, {"q": "Recraft AI est-il gratuit ?", "a": "Le plan gratuit de Recraft offre des crédits gratuits limités : trois générations par style et par jour, trois téléversements par jour, jusqu'à deux images par génération, et uniquement les modèles propres de Recraft. Les images du plan gratuit sont publiques, appartiennent à Recraft et ne sont pas sous licence pour un usage commercial. Les plans payants démarrent à 10$/mois facturé annuellement pour le plan Basic (1000 crédits/mois avec droits commerciaux), le plan Pro démarrant à 16$/mois facturé annuellement pour 2000 crédits, avec en plus les options Teams et Enterprise sur devis."}, {"q": "Quelle est la différence entre Recraft et Midjourney pour le travail de design ?", "a": "Recraft est optimisé pour les assets de design - vecteurs, icônes, visuels de marque cohérents. Midjourney est optimisé pour la qualité artistique des images. Les designers qui ont besoin de fichiers de production utilisent Recraft ; les artistes et créatifs utilisent Midjourney. Beaucoup de designers utilisent les deux pour des usages différents."}]$x$::jsonb
 WHERE slug = 'recraft-ai' AND lang = 'fr';

