UPDATE tools SET faq = $x$[{"q": "O que é Recraft AI?", "a": "Recraft AI é um gerador de imagens com IA especializado em gráficos vetoriais e design consistente com a marca. Ao contrário da maioria das ferramentas de IA que produzem imagens raster, o Recraft pode gerar arquivos SVG vetoriais verdadeiros, conjuntos de ícones e ativos de marca escaláveis. É popular entre designers que precisam de arquivos de design prontos para produção."}, {"q": "O Recraft AI pode gerar arquivos SVG?", "a": "Sim. Esse é o principal diferencial do Recraft — ele gera arquivos SVG (gráficos vetoriais escaláveis) verdadeiros, que podem ser redimensionados para qualquer tamanho sem perda de qualidade. Isso o torna essencial para design de logotipos, criação de ícones e qualquer trabalho de design para impressão ou grande formato."}, {"q": "O Recraft AI é gratuito?", "a": "O plano gratuito da Recraft oferece créditos gratuitos limitados: três gerações por estilo por dia, três uploads por dia, até duas imagens por geração e apenas os modelos próprios da Recraft. As imagens do plano gratuito são públicas, pertencem à Recraft e não têm licença para uso comercial. Os planos pagos começam em US$ 10/mês cobrados anualmente para o Basic (1.000 créditos/mês com direitos comerciais), com o Pro começando em US$ 16/mês cobrados anualmente por 2.000 créditos, além de opções Teams e Enterprise personalizadas."}, {"q": "Qual é a diferença entre Recraft e Midjourney para trabalhos de design?", "a": "Recraft é otimizado para ativos de design — vetores, ícones, visuais de marca consistentes. Midjourney é otimizado para qualidade artística de imagem. Designers que precisam de arquivos prontos para produção usam Recraft; artistas e profissionais criativos usam Midjourney. Muitos designers usam ambos para finalidades diferentes."}]$x$::jsonb
 WHERE slug = 'recraft-ai' AND lang = 'pt';

