 WHERE slug = 'gamma' AND lang = 'en';

UPDATE tools SET cons = ARRAY[$x$Credit-based usage means heavy generators can exhaust a plan's allowance quickly$x$, $x$Free plan output carries Gamma branding until you upgrade$x$, $x$Paid seat prices range from $12 to $100 per month depending on tier, with annual billing required to get the lower per-seat rate$x$, $x$Business requires annual billing at $40 per seat per month; no monthly Business option is listed$x$, $x$No separate Team plan is currently listed; multi-seat accounts fall under Business or custom Enterprise pricing$x$]::text[]
 WHERE slug = 'gamma' AND lang = 'en';

UPDATE tools SET choose_if = $x$["You want to turn a prompt or outline into a finished deck in minutes", "You want an AI agent that asks questions and keeps context while building your deck, with a freeform canvas when you need manual control", "You need presentations, documents, and simple sites from one tool", "You want to import an existing PowerPoint or PDF deck and keep working on it in Gamma", "You want a free starting point before committing to a paid tier"]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Gamma AI?", "a": "Gamma is an AI presentation tool that generates complete, designed presentations from a text prompt. Unlike traditional slide builders, Gamma creates card-based web presentations that are shared as links, generating content, layout, and visuals from your prompt. Gamma 5, the current release, adds an agent that asks questions and keeps context across edits, plus a freeform canvas for manual arrangement."}, {"q": "Is Gamma free?", "a": "Gamma has a free plan that grants 400 credits at signup with no time limit and no credit card required, enough for several presentations, though output carries Gamma branding. Paid seats cost $12 (Plus), $25 (Pro), or $100 (Ultra) per month billed monthly, or $9, $18, and $90 per month respectively if billed annually. Business costs $40 per seat per month billed annually. Enterprise pricing is custom."}, {"q": "Which is better for business presentations — Gamma or Beautiful.ai?", "a": "Both can produce professional results. Gamma exports to PowerPoint, PDF, PNG, and Google Slides on every plan, including Free, and Gamma 5 can import existing PowerPoint and PDF decks while preserving their design. Gamma suits fast, AI-generated decks shared as links, while Beautiful.ai focuses on template-based slide editing for teams that prefer a more traditional slide-by-slide workflow."}]$x$::jsonb
