UPDATE tools SET faq = $x$[{"q": "¿Qué es Gamma AI?", "a": "Gamma es una herramienta de presentaciones con IA que genera presentaciones completas y diseñadas a partir de un prompt de texto. A diferencia de los creadores de diapositivas tradicionales, Gamma crea presentaciones web basadas en tarjetas que se comparten como enlaces, generando contenido, diseño y elementos visuales a partir de tu prompt. Gamma 5, la versión actual, añade un agente que hace preguntas y mantiene el contexto a lo largo de las ediciones, además de un lienzo libre para la organización manual."}, {"q": "¿Es gratis Gamma?", "a": "Gamma tiene un plan gratuito que otorga 400 créditos al registrarse sin límite de tiempo y sin necesidad de tarjeta de crédito, suficiente para varias presentaciones, aunque el resultado lleva la marca de Gamma. Los puestos de pago cuestan 12 $ (Plus), 25 $ (Pro) o 100 $ (Ultra) al mes con facturación mensual, o 9 $, 18 $ y 90 $ al mes respectivamente con facturación anual. Business cuesta 40 $ por puesto al mes con facturación anual. El precio de Enterprise es personalizado."}, {"q": "¿Qué es mejor para presentaciones de negocios: Gamma o Beautiful.ai?", "a": "Ambas pueden producir resultados profesionales. Gamma exporta a PowerPoint, PDF, PNG y Google Slides en todos los planes, incluido el Free, y Gamma 5 puede importar presentaciones existentes de PowerPoint y PDF conservando su diseño. Gamma es adecuada para presentaciones rápidas generadas con IA y compartidas como enlaces, mientras que Beautiful.ai se centra en la edición de diapositivas basada en plantillas para equipos que prefieren un flujo de trabajo más tradicional, diapositiva por diapositiva."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'es';

