UPDATE tools SET faq = $x$[{"q": "Was ist Gamma AI?", "a": "Gamma ist ein KI-Präsentationstool, das vollständige, gestaltete Präsentationen aus einem Text-Prompt erzeugt. Anders als herkömmliche Folien-Tools erstellt Gamma kartenbasierte Web-Präsentationen, die als Links geteilt werden, wobei Inhalt, Layout und Visuals aus Ihrem Prompt generiert werden. Gamma 5, die aktuelle Version, fügt einen Agenten hinzu, der Fragen stellt und den Kontext über Bearbeitungen hinweg beibehält, sowie eine freie Bearbeitungsfläche für manuelles Anordnen."}, {"q": "Ist Gamma kostenlos?", "a": "Gamma bietet einen kostenlosen Plan, der bei der Anmeldung 400 Credits ohne zeitliches Limit und ohne Kreditkarte gewährt, was für mehrere Präsentationen ausreicht, wobei die Ausgaben jedoch Gamma-Branding tragen. Bezahlte Sitze kosten 12 $ (Plus), 25 $ (Pro) oder 100 $ (Ultra) pro Monat bei monatlicher Abrechnung, beziehungsweise 9 $, 18 $ und 90 $ pro Monat bei jährlicher Abrechnung. Business kostet 40 $ pro Sitz und Monat bei jährlicher Abrechnung. Die Enterprise-Preise sind individuell."}, {"q": "Was eignet sich besser für Geschäftspräsentationen — Gamma oder Beautiful.ai?", "a": "Beide können professionelle Ergebnisse liefern. Gamma exportiert in jedem Plan, einschließlich Free, nach PowerPoint, PDF, PNG und Google Slides, und Gamma 5 kann vorhandene PowerPoint- und PDF-Decks unter Beibehaltung ihres Designs importieren. Gamma eignet sich für schnelle, KI-generierte Decks, die als Links geteilt werden, während Beautiful.ai sich auf vorlagenbasierte Folienbearbeitung für Teams konzentriert, die einen eher traditionellen, folienweisen Arbeitsablauf bevorzugen."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'de';

