UPDATE tools SET faq = $x$[{"q": "Что такое Gamma AI?", "a": "Gamma — это инструмент для создания презентаций на основе ИИ, который генерирует полностью готовые, оформленные презентации по текстовому запросу. В отличие от традиционных конструкторов слайдов, Gamma создаёт веб-презентации на основе карточек, которыми делятся по ссылке, генерируя контент, макет и визуальное оформление на основе вашего запроса. Текущая версия, Gamma 5, добавляет агента, который задаёт вопросы и сохраняет контекст между правками, а также свободный холст для ручной расстановки элементов."}, {"q": "Является ли Gamma бесплатной?", "a": "У Gamma есть бесплатный тариф, который предоставляет 400 кредитов при регистрации без ограничения по времени и без необходимости указывать банковскую карту — этого достаточно для нескольких презентаций, хотя на выходных материалах присутствует брендинг Gamma. Платные места стоят $12 (Plus), $25 (Pro) или $100 (Ultra) в месяц при ежемесячной оплате, либо $9, $18 и $90 в месяц соответственно при годовой оплате. Business стоит $40 за место в месяц при годовой оплате. Цена Enterprise устанавливается индивидуально."}, {"q": "Что лучше подходит для деловых презентаций — Gamma или Beautiful.ai?", "a": "Оба инструмента способны давать профессиональный результат. Gamma поддерживает экспорт в PowerPoint, PDF, PNG и Google Slides на всех тарифах, включая Free, а Gamma 5 умеет импортировать существующие презентации PowerPoint и PDF с сохранением их дизайна. Gamma подходит для быстрого создания презентаций с помощью ИИ, которыми делятся по ссылке, тогда как Beautiful.ai сосредоточена на редактировании слайдов на основе шаблонов для команд, предпочитающих более традиционный пошаговый процесс работы со слайдами."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'ru';

