UPDATE tools SET faq = $x$[{"q": "מה זה Gamma AI?", "a": "Gamma הוא כלי מצגות AI שיוצר מצגות שלמות ומעוצבות מתוך פרומפט טקסטואלי. בניגוד לבוני שקופיות מסורתיים, Gamma יוצר מצגות אינטרנט מבוססות-כרטיסים המשותפות בתור קישורים, ומייצר תוכן, פריסה וויזואליה מתוך הפרומפט שלך. Gamma 5, הגרסה הנוכחית, מוסיפה סוכן ששואל שאלות ושומר הקשר לאורך עריכות, בנוסף ללוח חופשי לסידור ידני."}, {"q": "האם Gamma חינמי?", "a": "ל-Gamma יש תוכנית חינמית שמעניקה 400 קרדיטים בהרשמה ללא הגבלת זמן וללא צורך בכרטיס אשראי, מספיקים למספר מצגות, אם כי הפלט נושא מיתוג Gamma. משתמשים בתשלום עולים 12$ (Plus), 25$ (Pro), או 100$ (Ultra) בחודש בחיוב חודשי, או 9$, 18$ ו-90$ בחודש בהתאמה בחיוב שנתי. Business עולה 40$ למשתמש בחודש בחיוב שנתי. תמחור Enterprise הוא מותאם אישית."}, {"q": "מה עדיף למצגות עסקיות — Gamma או Beautiful.ai?", "a": "שניהם יכולים להפיק תוצאות מקצועיות. Gamma מייצא ל-PowerPoint, PDF, PNG ו-Google Slides בכל התוכניות, כולל Free, ו-Gamma 5 יכול לייבא מצגות PowerPoint ו-PDF קיימות תוך שמירה על העיצוב שלהן. Gamma מתאים למצגות מהירות שנוצרות על ידי AI ומשותפות כקישורים, בעוד ש-Beautiful.ai מתמקד בעריכת שקופיות מבוססת-תבניות לצוותים שמעדיפים תהליך עבודה מסורתי יותר של שקופית אחר שקופית."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'he';

