UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Gamma AI ?", "a": "Gamma est un outil de présentation IA qui génère des présentations complètes et conçues à partir d'un prompt textuel. Contrairement aux créateurs de diapositives traditionnels, Gamma crée des présentations web en forme de cartes partagées sous forme de liens, en générant le contenu, la mise en page et les visuels à partir de votre prompt. Gamma 5, la version actuelle, ajoute un agent qui pose des questions et conserve le contexte au fil des modifications, ainsi qu'un canevas libre pour l'agencement manuel."}, {"q": "Gamma est-il gratuit ?", "a": "Gamma propose un plan gratuit qui accorde 400 crédits à l'inscription sans limite de temps et sans carte bancaire requise, suffisant pour plusieurs présentations, bien que les contenus produits comportent la marque Gamma. Les plans payants coûtent 12 $ (Plus), 25 $ (Pro) ou 100 $ (Ultra) par mois en facturation mensuelle, ou respectivement 9 $, 18 $ et 90 $ par mois en facturation annuelle. Business coûte 40 $ par utilisateur et par mois en facturation annuelle. La tarification Enterprise est personnalisée."}, {"q": "Lequel est préférable pour les présentations professionnelles — Gamma ou Beautiful.ai ?", "a": "Les deux peuvent produire des résultats professionnels. Gamma exporte en PowerPoint, PDF, PNG et Google Slides sur tous les plans, y compris Free, et Gamma 5 peut importer des présentations PowerPoint et PDF existantes en préservant leur design. Gamma convient aux présentations générées rapidement par IA et partagées sous forme de liens, tandis que Beautiful.ai se concentre sur l'édition de diapositives basée sur des modèles pour les équipes qui préfèrent un flux de travail plus traditionnel diapositive par diapositive."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'fr';

