UPDATE tools SET faq = $x$[{"a": "OpenCode is an open-source AI coding agent built by Anomaly, available as a terminal interface, desktop app, and IDE extension. It supports 75+ LLM providers through Models.dev, including Claude, GPT, Gemini, and local models. The core agent is free — you bring your own API keys, or log in with a GitHub Copilot or ChatGPT Plus/Pro account.", "q": "What is OpenCode?"}, {"a": "The OpenCode agent itself is free and open source — you pay only for the LLM API calls you make to your chosen provider, or nothing with local models. Anomaly also offers OpenCode Zen, a pay-as-you-go gateway to curated models priced per 1 million tokens with zero markup, OpenCode Go, a $10/month subscription (Go Plus at $40/month) for curated low-cost open models with usage limits, and an Enterprise tier with unpublished pricing.", "q": "Is OpenCode free?"}, {"a": "Aider is a terminal-focused coding agent with a longer track record and strong git integration. OpenCode is newer and now available as a terminal interface, desktop app, and IDE extension, with support for 75+ LLM providers via Models.dev. Both are open source — try both to see which workflow fits better.", "q": "What is the difference between OpenCode and Aider?"}]$x$::jsonb
