UPDATE tools SET description = $x$Agent de codage open source développé par Anomaly, disponible sous forme d'interface terminal, d'application de bureau et d'extension IDE, prenant en charge plus de 75 fournisseurs de LLM via Models.dev — l'agent principal est gratuit à utiliser avec vos propres clés API ou une connexion par abonnement pris en charge.$x$
