UPDATE tools SET faq = $x$[{"q": "¿Qué es Claude Code?", "a": "Claude Code es el agente de codificación oficial de Anthropic. Lee tu base de código, escribe código, ejecuta comandos, corrige errores y completa tareas multiarchivo de forma autónoma, funcionando desde la terminal, VS Code, JetBrains, una aplicación de escritorio o la web."}, {"q": "¿Cuánto cuesta Claude Code?", "a": "Claude Code está incluido con los planes Claude Pro (desde $17/mes con facturación anual, $20/mes con facturación mensual), Max (desde $100/mes), Team Standard, Team Premium y Enterprise. En estos planes, Claude Code comparte el mismo grupo de uso que tus chats de Claude; también está disponible el uso de API de pago por uso por separado a través de la Anthropic Console."}, {"q": "¿En qué se diferencia Claude Code de Cursor?", "a": "Claude Code también funciona como extensiones de VS Code y JetBrains, una aplicación de escritorio y en la web, no solo en la terminal. Está diseñado para desarrolladores que quieren un agente que lea, edite y ejecute código en todo su flujo de trabajo, mientras que Cursor es un IDE completo basado en VS Code con una interfaz visual."}, {"q": "¿Qué puede hacer Claude Code de forma autónoma?", "a": "Claude Code puede leer y editar archivos, ejecutar comandos de shell, ejecutar pruebas, buscar en la base de código, gestionar git y completar tareas de ingeniería de varios pasos de principio a fin con una indicación mínima."}]$x$::jsonb
