UPDATE tools SET faq = $x$[{"q": "Що таке Claude Code?", "a": "Claude Code — це офіційний агент для програмування від Anthropic. Він читає ваш кодову базу, пише код, виконує команди, виправляє помилки та автономно виконує багатофайлові завдання, працюючи в терміналі, VS Code, JetBrains, десктопному застосунку або в вебі."}, {"q": "Скільки коштує Claude Code?", "a": "Claude Code включено до планів Claude Pro (від 17 $/місяць при річній оплаті, 20 $/місяць при помісячній), Max (від 100 $/місяць), Team Standard, Team Premium та Enterprise. На цих планах Claude Code використовує той самий пул ресурсів, що й ваші чати з Claude; також доступне окреме використання API з оплатою за фактичне використання через Anthropic Console."}, {"q": "Чим Claude Code відрізняється від Cursor?", "a": "Claude Code також працює як розширення для VS Code і JetBrains, як десктопний застосунок та в вебі, а не лише в терміналі. Він створений для розробників, які хочуть мати агента, що читає, редагує та виконує код у межах їхнього робочого процесу, тоді як Cursor — це повноцінне IDE на основі VS Code з візуальним інтерфейсом."}, {"q": "Що Claude Code може робити автономно?", "a": "Claude Code може читати та редагувати файли, виконувати команди оболонки, запускати тести, шукати по кодовій базі, керувати git та виконувати багатоетапні інженерні завдання від початку до кінця з мінімальними підказками."}]$x$::jsonb
 WHERE slug = 'claude-code' AND lang = 'ua';

