UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Claude Code ?", "a": "Claude Code est l'agent de codage officiel d'Anthropic. Il lit votre base de code, écrit du code, exécute des commandes, corrige des bugs et accomplit des tâches multi-fichiers de manière autonome, en fonctionnant depuis le terminal, VS Code, JetBrains, une application de bureau ou le web."}, {"q": "Combien coûte Claude Code ?", "a": "Claude Code est inclus avec les plans Claude Pro (à partir de 17 $/mois facturé annuellement, 20 $/mois facturé mensuellement), Max (à partir de 100 $/mois), Team Standard, Team Premium et Enterprise. Sur ces plans, Claude Code partage le même quota d'usage que vos conversations Claude ; un usage API séparé à l'usage est également disponible via la Console Anthropic."}, {"q": "En quoi Claude Code diffère-t-il de Cursor ?", "a": "Claude Code fonctionne aussi comme extensions VS Code et JetBrains, comme application de bureau et sur le web, pas uniquement dans le terminal. Il est conçu pour les développeurs qui veulent un agent capable de lire, modifier et exécuter du code dans tout leur workflow, tandis que Cursor est un IDE complet basé sur VS Code avec une interface visuelle."}, {"q": "Que peut faire Claude Code de manière autonome ?", "a": "Claude Code peut lire et modifier des fichiers, exécuter des commandes shell, lancer des tests, rechercher dans la base de code, gérer git et accomplir des tâches d'ingénierie en plusieurs étapes de bout en bout avec un minimum d'instructions."}]$x$::jsonb
