UPDATE tools SET faq = $x$[{"q": "O que é o Claude Code?", "a": "Claude Code é o agente de codificação oficial da Anthropic. Ele lê sua base de código, escreve código, executa comandos, corrige bugs e conclui tarefas multi-arquivo de forma autônoma, funcionando a partir do terminal, VS Code, JetBrains, um aplicativo desktop ou a web."}, {"q": "Quanto custa o Claude Code?", "a": "O Claude Code está incluído nos planos Claude Pro (a partir de $17/mês cobrado anualmente, $20/mês cobrado mensalmente), Max (a partir de $100/mês), Team Standard, Team Premium e Enterprise. Nesses planos, o Claude Code compartilha o mesmo pool de uso dos seus chats com o Claude; o uso de API pré-pago separado também está disponível pelo Anthropic Console."}, {"q": "Qual a diferença entre o Claude Code e o Cursor?", "a": "O Claude Code também funciona como extensões para VS Code e JetBrains, um aplicativo desktop e na web, não apenas no terminal. Ele foi feito para desenvolvedores que querem um agente que lê, edita e executa código em todo o seu workflow, enquanto o Cursor é uma IDE completa construída sobre o VS Code com uma interface visual."}, {"q": "O que o Claude Code pode fazer de forma autônoma?", "a": "O Claude Code pode ler e editar arquivos, executar comandos de shell, rodar testes, pesquisar na base de código, gerenciar o git e concluir tarefas de engenharia em várias etapas de ponta a ponta com o mínimo de prompts."}]$x$::jsonb
