 WHERE slug = 'remove-bg' AND lang = 'en';

UPDATE tools SET cons = ARRAY[$x$The standalone remove.bg website, accounts, API, apps, and integrations shut down on December 1, 2026$x$, $x$The free web tool only outputs low-resolution previews up to 0.25 MP, and this free tier disappears entirely after the shutdown$x$, $x$Any full-resolution download requires paid credits, and unused pay-as-you-go credits expire on December 1, 2026 rather than lasting indefinitely$x$, $x$After the shutdown, the self-service API is discontinued; developers must migrate to Leonardo.ai's separate API$x$, $x$Tricky edges, cluttered backgrounds, or low contrast can still need manual cleanup$x$]::text[]
