 WHERE slug = 'remove-bg' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Remove.bg?", "a": "Remove.bg is an AI-powered background removal tool that automatically detects and removes image backgrounds in seconds, known for accurate edge detection especially around hair and complex objects, with a developer API for bulk processing. However, according to remove.bg's own FAQ, the standalone website, accounts, API, and apps are being discontinued on December 1, 2026, with the technology moving into Canva and the API moving to Leonardo.ai."}, {"q": "Is Remove.bg free?", "a": "For now, a free account gives low-resolution web previews capped at 0.25 MP, plus the first 50 API or app calls each month at no charge; full-resolution results require credits or a subscription starting at $9 per month billed monthly. This free tier and the rest of the standalone service end on December 1, 2026, after which background removal continues only through Canva's own plans or the separate Leonardo.ai API."}, {"q": "Does Canva remove backgrounds for free?", "a": "Canva's help center lists its own Background Remover as part of Canva Pro, Business, Education, and Nonprofits plans. Remove.bg's FAQ states this Canva feature uses the same background-removal technology as remove.bg, and Canva is consolidating the two: remove.bg's standalone product closes on December 1, 2026, with background removal moving fully into Canva."}, {"q": "Which has better background removal quality?", "a": "According to remove.bg's own FAQ, Canva's Background Remover uses the same background-removal technology as remove.bg, so quality should be comparable rather than one being clearly superior. As remove.bg's standalone service winds down by December 1, 2026, Canva's integrated tool and Leonardo.ai's API become the ongoing ways to get this same technology."}]$x$::jsonb
 WHERE slug = 'remove-bg' AND lang = 'en';

