UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Remove.bg ?", "a": "Remove.bg est un outil de suppression d'arrière-plan basé sur l'IA qui détecte et supprime automatiquement l'arrière-plan des images en quelques secondes, réputé pour sa détection précise des contours, notamment autour des cheveux et des objets complexes, avec une API développeur pour le traitement en masse. Cependant, selon la propre FAQ de remove.bg, le site web, les comptes, l'API et les applications autonomes seront abandonnés le 1 décembre 2026, la technologie étant intégrée à Canva et l'API transférée vers Leonardo.ai."}, {"q": "Remove.bg est-il gratuit ?", "a": "Pour l'instant, un compte gratuit donne accès à des aperçus web basse résolution plafonnés à 0,25 MP, ainsi qu'aux 50 premiers appels API ou application par mois gratuitement ; les résultats en pleine résolution nécessitent des crédits ou un abonnement à partir de 9 $ par mois en facturation mensuelle. Ce niveau gratuit, ainsi que le reste du service autonome, prendront fin le 1 décembre 2026, après quoi la suppression d'arrière-plan ne se poursuivra que via les propres forfaits de Canva ou l'API distincte de Leonardo.ai."}, {"q": "Canva supprime-t-il les arrière-plans gratuitement ?", "a": "Le centre d'aide de Canva répertorie son propre Background Remover comme faisant partie des forfaits Canva Pro, Business, Education et Nonprofits. La FAQ de remove.bg indique que cette fonctionnalité de Canva utilise la même technologie de suppression d'arrière-plan que remove.bg, et Canva consolide les deux : le produit autonome de remove.bg ferme le 1 décembre 2026, la suppression d'arrière-plan étant entièrement intégrée à Canva."}, {"q": "Lequel offre une meilleure qualité de suppression d'arrière-plan ?", "a": "Selon la propre FAQ de remove.bg, le Background Remover de Canva utilise la même technologie de suppression d'arrière-plan que remove.bg, la qualité devrait donc être comparable plutôt que l'un étant clairement supérieur à l'autre. À mesure que le service autonome de remove.bg sera démantelé d'ici le 1 décembre 2026, l'outil intégré de Canva et l'API de Leonardo.ai deviendront les moyens pérennes d'accéder à cette même technologie."}]$x$::jsonb
 WHERE slug = 'remove-bg' AND lang = 'fr';

