UPDATE tools SET faq = $x$[{"a": "Whisper is OpenAI's open-source speech recognition model. Released in 2022, it transcribes audio in around 99 languages with high accuracy. It's a developer tool — not a consumer app — that runs locally or via API. Many transcription apps are built on top of Whisper.", "q": "What is OpenAI Whisper?"}, {"a": "Whisper's open-source weights are completely free to download and run locally. OpenAI also offers Whisper-based models through its API on a per-minute basis, starting at $0.0045/min for gpt-transcribe. Consumer apps built on Whisper typically charge their own subscription fees.", "q": "Is Whisper free?"}, {"a": "This claim could not be verified against a primary source, so we cannot confirm whether Otter.ai is built on Whisper.", "q": "Is Otter.ai built on Whisper?"}, {"a": "This comparison could not be verified against a primary source, so we cannot make a reliable accuracy comparison between Whisper and Otter.ai.", "q": "Which is more accurate — Whisper or Otter.ai?"}]$x$::jsonb
