UPDATE tools SET faq = $x$[{"a": "Whisper es el modelo de reconocimiento de voz de código abierto de OpenAI. Lanzado en 2022, transcribe audio en aproximadamente 99 idiomas con alta precisión. Es una herramienta para desarrolladores — no una aplicación de consumo — que funciona localmente o a través de API. Muchas aplicaciones de transcripción están construidas sobre Whisper.", "q": "¿Qué es OpenAI Whisper?"}, {"a": "Los pesos de código abierto de Whisper son completamente gratuitos para descargar y ejecutar localmente. OpenAI también ofrece modelos basados en Whisper a través de su API por minuto, a partir de 0,0045 $/min para gpt-transcribe. Las aplicaciones de consumo construidas sobre Whisper suelen cobrar sus propias tarifas de suscripción.", "q": "¿Es gratis Whisper?"}, {"a": "Esta afirmación no pudo verificarse con una fuente primaria, por lo que no podemos confirmar si Otter.ai está construido sobre Whisper.", "q": "¿Está Otter.ai construido sobre Whisper?"}, {"a": "Esta comparación no pudo verificarse con una fuente primaria, por lo que no podemos hacer una comparación de precisión fiable entre Whisper y Otter.ai.", "q": "¿Cuál es más preciso: Whisper u Otter.ai?"}]$x$::jsonb
