UPDATE tools SET faq = $x$[{"a": "Whisper ist OpenAIs Open-Source-Spracherkennungsmodell. Es wurde 2022 veröffentlicht und transkribiert Audio in rund 99 Sprachen mit hoher Genauigkeit. Es ist ein Entwicklerwerkzeug — keine Verbraucher-App — das lokal oder über eine API läuft. Viele Transkriptions-Apps basieren auf Whisper.", "q": "Was ist OpenAI Whisper?"}, {"a": "Whispers Open-Source-Gewichte sind völlig kostenlos herunterladbar und lokal ausführbar. OpenAI bietet außerdem Whisper-basierte Modelle über seine API auf Minutenbasis an, ab 0,0045 $/Min. für gpt-transcribe. Verbraucher-Apps, die auf Whisper basieren, erheben in der Regel eigene Abonnementgebühren.", "q": "Ist Whisper kostenlos?"}, {"a": "Diese Behauptung konnte nicht anhand einer Primärquelle überprüft werden, daher können wir nicht bestätigen, ob Otter.ai auf Whisper basiert.", "q": "Basiert Otter.ai auf Whisper?"}, {"a": "Dieser Vergleich konnte nicht anhand einer Primärquelle überprüft werden, daher können wir keinen verlässlichen Genauigkeitsvergleich zwischen Whisper und Otter.ai vornehmen.", "q": "Was ist genauer — Whisper oder Otter.ai?"}]$x$::jsonb
