UPDATE tools SET faq = $x$[{"a": "Whisper — це модель розпізнавання мовлення OpenAI з відкритим кодом. Випущена у 2022 році, вона транскрибує аудіо приблизно 99 мовами з високою точністю. Це інструмент для розробників — не споживчий застосунок — який працює локально або через API. Багато застосунків для транскрибування побудовані на основі Whisper.", "q": "Що таке OpenAI Whisper?"}, {"a": "Ваги Whisper з відкритим кодом повністю безкоштовні для завантаження та локального запуску. OpenAI також пропонує моделі на основі Whisper через свій API з оплатою за хвилину, починаючи з $0,0045/хв для gpt-transcribe. Споживчі застосунки, побудовані на Whisper, зазвичай стягують власну плату за підписку.", "q": "Чи безкоштовний Whisper?"}, {"a": "Це твердження неможливо перевірити за першоджерелом, тому ми не можемо підтвердити, чи побудований Otter.ai на основі Whisper.", "q": "Чи побудований Otter.ai на основі Whisper?"}, {"a": "Це порівняння неможливо перевірити за першоджерелом, тому ми не можемо зробити достовірне порівняння точності між Whisper і Otter.ai.", "q": "Що точніше — Whisper чи Otter.ai?"}]$x$::jsonb
