UPDATE tools SET faq = $x$[{"a": "Whisper הוא מודל זיהוי דיבור בקוד פתוח של OpenAI. שפורסם בשנת 2022, הוא מתמלל אודיו בכ-99 שפות בדיוק גבוה. זהו כלי פיתוח — לא אפליקציה צרכנית — שרץ באופן מקומי או דרך API. אפליקציות תמלול רבות בנויות על גבי Whisper.", "q": "מהו OpenAI Whisper?"}, {"a": "המשקלים בקוד הפתוח של Whisper חינמיים לחלוטין להורדה והרצה מקומית. OpenAI מציעה גם מודלים מבוססי Whisper דרך ה-API שלה בתשלום לפי דקה, החל מ-0.0045$ לדקה עבור gpt-transcribe. אפליקציות צרכניות הבנויות על Whisper גובות בדרך כלל דמי מנוי משלהן.", "q": "האם Whisper חינמי?"}, {"a": "לא ניתן היה לאמת טענה זו מול מקור ראשוני, ולכן איננו יכולים לאשר אם Otter.ai בנוי על Whisper.", "q": "האם Otter.ai בנוי על Whisper?"}, {"a": "לא ניתן היה לאמת השוואה זו מול מקור ראשוני, ולכן איננו יכולים לספק השוואת דיוק אמינה בין Whisper ל-Otter.ai.", "q": "מה מדויק יותר — Whisper או Otter.ai?"}]$x$::jsonb
