UPDATE tools SET faq = $x$[{"a": "Whisper est le modèle open source de reconnaissance vocale d'OpenAI. Publié en 2022, il transcrit l'audio dans environ 99 langues avec une grande précision. C'est un outil pour développeurs — pas une application grand public — qui fonctionne en local ou via API. De nombreuses applications de transcription sont construites sur Whisper.", "q": "Qu'est-ce qu'OpenAI Whisper ?"}, {"a": "Les poids open source de Whisper sont totalement gratuits à télécharger et à exécuter en local. OpenAI propose également des modèles basés sur Whisper via son API, facturés à la minute, à partir de 0,0045 $/min pour gpt-transcribe. Les applications grand public construites sur Whisper facturent généralement leurs propres abonnements.", "q": "Whisper est-il gratuit ?"}, {"a": "Cette affirmation n'a pas pu être vérifiée auprès d'une source primaire, nous ne pouvons donc pas confirmer si Otter.ai est construit sur Whisper.", "q": "Otter.ai est-il construit sur Whisper ?"}, {"a": "Cette comparaison n'a pas pu être vérifiée auprès d'une source primaire, nous ne pouvons donc pas établir de comparaison fiable de précision entre Whisper et Otter.ai.", "q": "Lequel est le plus précis — Whisper ou Otter.ai ?"}]$x$::jsonb
