UPDATE tools SET faq = $x$[{"a": "Whisper é o modelo de reconhecimento de fala de código aberto da OpenAI. Lançado em 2022, ele transcreve áudio em cerca de 99 idiomas com alta precisão. É uma ferramenta para desenvolvedores — não um aplicativo para consumidor final — que roda localmente ou via API. Muitos aplicativos de transcrição são construídos sobre o Whisper.", "q": "O que é o OpenAI Whisper?"}, {"a": "Os pesos de código aberto do Whisper são completamente gratuitos para baixar e executar localmente. A OpenAI também oferece modelos baseados no Whisper através de sua API, cobrados por minuto, a partir de US$ 0,0045/min para o gpt-transcribe. Aplicativos para consumidor final construídos sobre o Whisper geralmente cobram suas próprias taxas de assinatura.", "q": "O Whisper é gratuito?"}, {"a": "Essa afirmação não pôde ser verificada em uma fonte primária, então não podemos confirmar se o Otter.ai é construído sobre o Whisper.", "q": "O Otter.ai é construído sobre o Whisper?"}, {"a": "Essa comparação não pôde ser verificada em uma fonte primária, então não podemos fazer uma comparação de precisão confiável entre Whisper e Otter.ai.", "q": "Qual é mais preciso — Whisper ou Otter.ai?"}]$x$::jsonb
 WHERE slug = 'whisper' AND lang = 'pt';

