 WHERE slug = 'relevance-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Relevance AI is a platform for building AI agents and multi-agent systems without deep coding. Agents can use tools, search the web, read documents, and call APIs to complete complex multi-step tasks. It's used for sales automation, research, customer support, and data enrichment.", "q": "What is Relevance AI?"}, {"a": "No. Relevance AI's Free plan has been retired for both new signups and existing accounts. Per the vendor's docs, Pro starts at $19/month billed annually ($29/month billed monthly), and Team starts at $234/month billed annually ($349/month billed monthly). Enterprise pricing is custom and quoted via sales.", "q": "Is Relevance AI free?"}, {"a": "Zapier automates fixed rule-based workflows between apps. Relevance AI builds AI agents that reason and adapt — they use AI models to decide what to do next. Zapier is deterministic automation; Relevance is autonomous AI decision-making.", "q": "What is the difference between Relevance AI and Zapier?"}, {"a": "Copilot Studio can build agents that perform actions, but it's primarily designed for conversational chatbots within Microsoft's ecosystem. Relevance AI is more specialized for complex multi-step autonomous agents that can use many external tools.", "q": "Can Copilot Studio build autonomous agents?"}]$x$::jsonb
 WHERE slug = 'relevance-ai' AND lang = 'en';

