UPDATE tools SET choose_if = $x$["✅ Sie möchten Multi-Agent-KI-Pipelines und autonome KI-Workflows ohne tiefgehende Programmierkenntnisse erstellen", "✅ Sie benötigen KI-Agenten, die Tools nutzen, im Web recherchieren, Dokumente analysieren und APIs aufrufen", "✅ Sie bauen einen Vertriebs-KI-Agenten, Rechercheagenten oder Support-Agenten, der Aufgaben eigenständig erledigt", "✅ Sie möchten flexibel jedes beliebige KI-Modell (OpenAI, Anthropic, Google) für Ihre Agenten wählen können"]$x$::jsonb
