UPDATE tools SET faq = $x$[{"a": "Relevance AI — это платформа для создания ИИ-агентов и многоагентных систем без глубокого программирования. Агенты могут использовать инструменты, искать информацию в интернете, читать документы и вызывать API для выполнения сложных многоэтапных задач. Используется для автоматизации продаж, исследований, поддержки клиентов и обогащения данных.", "q": "Что такое Relevance AI?"}, {"a": "Нет. Бесплатный тариф Relevance AI упразднён как для новых регистраций, так и для существующих аккаунтов. Согласно документации поставщика, тариф Pro начинается от $19/месяц при годовой оплате ($29/месяц при помесячной оплате), а тариф Team — от $234/месяц при годовой оплате ($349/месяц при помесячной оплате). Цена Enterprise индивидуальна и уточняется через отдел продаж.", "q": "Relevance AI бесплатен?"}, {"a": "Zapier автоматизирует фиксированные, основанные на правилах рабочие процессы между приложениями. Relevance AI создаёт ИИ-агентов, которые рассуждают и адаптируются — они используют ИИ-модели, чтобы решать, что делать дальше. Zapier — это детерминированная автоматизация, Relevance — автономное принятие решений ИИ.", "q": "В чём разница между Relevance AI и Zapier?"}, {"a": "Copilot Studio может создавать агентов, выполняющих действия, но он в первую очередь предназначен для диалоговых чат-ботов в экосистеме Microsoft. Relevance AI больше специализируется на сложных многоэтапных автономных агентах, способных использовать множество внешних инструментов.", "q": "Может ли Copilot Studio создавать автономных агентов?"}]$x$::jsonb
 WHERE slug = 'relevance-ai' AND lang = 'ru';

