UPDATE tools SET description = $x$פלטפורמה ללא קוד לבניית סוכני AI וצוותי רב-סוכנים לתהליכי עבודה עסקיים.$x$
 WHERE slug = 'relevance-ai' AND lang = 'he';

UPDATE tools SET description_long = $x$Relevance AI היא פלטפורמה ללא קוד לבניית ופריסת סוכני AI וצוותי רב-סוכנים. ההתמחות שלה היא תזמור רב-סוכנים (multi-agent orchestration) — מערכות שבהן סוכנים מתמחים (חוקר, כותב, בודק איכות) משתפים פעולה כדי להשלים תהליכי עבודה מורכבים שסוכן בודד לא יכול לטפל בהם באופן אמין.

החברה מיקמה את עצמה מחדש כלפי רוכשים ארגוניים תחת מסגור של 'AI Workforce'. בספטמבר 2026 היא הכריזה על Invent 2.0, סוכן לתכנון, בנייה וניהול של כוחות עבודה מבוססי סוכני AI, שממפה תהליכים, מרכיב ארכיטקטורות רב-סוכנים, קובע אמות מידה (benchmarks) ומנטר איכות. דף התמחור הציבורי שלה מציג כעת רק מסלול Enterprise עם קריאה לפעולה 'Talk to sales' וללא מספרים מפורסמים. תמחור Pro ו-Team לשירות עצמי עדיין מופיע בדפי התיעוד של הספק. אין מסלול חינמי: תיעוד הספק עצמו קובע שמסלול ה-Free הוצא משימוש הן עבור נרשמים חדשים והן עבור חשבונות קיימים.

הפלטפורמה כוללת בונה תהליכי עבודה ויזואלי, כוונון עדין (fine-tuning) על מסמכים ייחודיים לחברה, ותזמור רב-סוכנים המטפל אוטומטית בהאצלת משימות, איסוף תוצאות ובדיקת איכות. הסוכנים מתחברים למערכות CRM, מסדי נתונים, Slack ודוא"ל, ומסלול ה-Enterprise מפרסם מעל 2,000 אינטגרציות.

התמחור מחולק לשני מרכיבים: Actions (מה שהסוכנים עושים) ו-Vendor Credits (עלויות המודלים, מועברות במחיר סיטונאי ללא תוספת רווח). לפי תיעוד הספק, Pro עולה 19$ לחודש בחיוב שנתי או 29$ לחודש בחיוב חודשי, וכולל 2,500 פעולות ו-20$ של קרדיט ספק בחודש. Team עולה 234$ לחודש בחיוב שנתי או 349$ לחודש בחיוב חודשי, וכולל 7,000 פעולות ו-70$ של קרדיט ספק בחודש, בנוסף לסוכני שיחה, סוכני פגישות ולוח בקרה אנליטי. Enterprise מותאם אישית, מתומחר דרך מכירות, ומוסיף סוכנים, משתמשים ופרויקטים ללא הגבלה, מעל 2,000 אינטגרציות, טריגרים ארגוניים, הערכות סוכנים, בדיקות A/B, SSO, RBAC, יומני ביקורת ומנהל חשבון ייעודי.

מגבלות: עקומת למידה תלולה יותר מכלים פשוטים יותר כמו Lindy; מסלול Team יקר עבור צוותים קטנים; המעבר לדף תמחור ציבורי שמיועד רק ל-Enterprise הופך את הרכישה בשירות עצמי לפחות שקופה; ומודל התמחור הדו-מטבעי (actions ו-credits) עלול לבלבל משתמשים חדשים. מתאים בעיקר לצוותי revenue operations, אוטומציית שיווק ותמיכה — ובמידה גוברת לרוכשים ארגוניים — הזקוקים לתהליכי עבודה רב-סוכנים שמטפלים בתהליכים עסקיים מורכבים ורב-שלביים.$x$
 WHERE slug = 'relevance-ai' AND lang = 'he';

