UPDATE tools SET faq = $x$[{"q": "Wofür wird Copy.ai verwendet?", "a": "Copy.ai positioniert sich heute als GTM-KI-Plattform, die eine Chat-Oberfläche zum Verfassen von Marketinginhalten (Anzeigentexte, E-Mail-Betreffzeilen, Produktbeschreibungen, Social-Media-Posts) mit mehrstufigen Workflows und Agenten kombiniert, die Go-to-Market-Aufgaben für Sales-, Marketing- und RevOps-Teams automatisieren."}, {"q": "Ist Copy.ai kostenlos?", "a": "Es gibt keinen kostenlosen Plan. Die Einstiegsstufe ist Chat für $29/Monat bei monatlicher Abrechnung. Darüber ist die einzige veröffentlichte Option eine individuell bepreiste Enterprise-Stufe, die per Demo verfügbar ist."}, {"q": "Was ist der Unterschied zwischen Copy.ai und Jasper?", "a": "Copy.ai konzentriert sich jetzt auf GTM-Workflow-Automatisierung für Sales-, Marketing- und RevOps-Teams, mit einem $29/Monat-Chat-Plan und individueller Enterprise-Preisgestaltung darüber. Jasper konzentriert sich auf markenkonsistente Langform-Inhalte für Enterprise-Teams. Copy.ai eignet sich besser für Teams, die Workflow- und Agentenautomatisierung benötigen; Jasper ist besser für Teams mit strikten Markenrichtlinien."}]$x$::jsonb
