UPDATE tools SET faq = $x$[{"q": "À quoi sert Copy.ai ?", "a": "Copy.ai se positionne désormais comme une plateforme GTM AI, combinant une interface de chat pour rédiger du contenu marketing (textes publicitaires, lignes d'objet d'e-mail, descriptions de produits, posts sur les réseaux sociaux) avec des Workflows et agents multi-étapes qui automatisent les tâches go-to-market pour les équipes de ventes, de marketing et de RevOps."}, {"q": "Copy.ai est-il gratuit ?", "a": "Aucun plan gratuit. Le niveau d'entrée est Chat à 29 $/mois facturé mensuellement. Au-dessus, la seule option publiée est un niveau Enterprise à tarification personnalisée disponible sur demande de démo."}, {"q": "Quelle est la différence entre Copy.ai et Jasper ?", "a": "Copy.ai se concentre désormais sur l'automatisation des workflows GTM pour les équipes de ventes, de marketing et de RevOps, avec un plan Chat à 29 $/mois et une tarification Enterprise personnalisée au-dessus. Jasper se concentre sur du contenu long format cohérent avec la marque pour les équipes d'entreprise. Copy.ai convient mieux aux équipes qui ont besoin d'automatisation de workflows et d'agents ; Jasper convient mieux aux équipes avec des directives de marque strictes."}]$x$::jsonb
