UPDATE tools SET faq = $x$[{"q": "Ist SEMrush den Preis wert?", "a": "Für ernsthafte SEO-Profis und Agenturen gilt SEMrush im Allgemeinen als den veröffentlichten Preis von 139–299 $/Monat bei monatlicher Abrechnung (etwa 117–248 $/Monat bei jährlicher Zahlung) wert. Die oberste Advanced-Stufe ist individuell bepreist und erfordert Kontakt zum Vertrieb. Es ersetzt mehrere eigenständige Tools (Keyword-Recherche, Backlink-Checker, Site-Audit, Ranking-Tracking). Für kleine Unternehmen mit einfacher SEO können günstigere Alternativen wie Ubersuggest ausreichen."}, {"q": "Kann Frase SEMrush ersetzen?", "a": "Nein. Frase konzentriert sich auf Content-Optimierung — es bietet keine vollständige Keyword-Recherche, Backlink-Analyse oder technische SEO-Audits wie SEMrush. Frase wird häufig zusammen mit SEMrush verwendet: SEMrush für Strategie und Keyword-Recherche, Frase für Content-Erstellung und -Optimierung."}]$x$::jsonb
 WHERE slug = 'semrush' AND lang = 'de';

