UPDATE tools SET faq = $x$[{"q": "Стоит ли SEMrush своих денег?", "a": "Для серьёзных SEO-специалистов и агентств SEMrush в целом считается оправданным по своей опубликованной цене $139–299 в месяц при помесячной оплате (около $117–248 в месяц при годовой оплате). Верхний тариф Advanced имеет индивидуальную цену и требует связи с отделом продаж. Он заменяет несколько отдельных инструментов (исследование ключевых слов, проверка обратных ссылок, аудит сайта, отслеживание позиций). Для малого бизнеса, занимающегося базовым SEO, могут подойти более дешёвые альтернативы, такие как Ubersuggest."}, {"q": "Может ли Frase заменить SEMrush?", "a": "Нет. Frase фокусируется на оптимизации контента — он не выполняет полноценное исследование ключевых слов, анализ обратных ссылок или технический SEO-аудит так, как это делает SEMrush. Frase часто используется вместе с SEMrush: SEMrush — для стратегии и исследования ключевых слов, Frase — для создания и оптимизации контента."}]$x$::jsonb
 WHERE slug = 'semrush' AND lang = 'ru';

